import sailpoint.object.EmailTemplate;
import sailpoint.object.EmailOptions;
import sailpoint.object.Identity;
import java.util.HashMap;
import java.util.Map;

// Resolve the target identity so we can work out a recipient.
Identity target = null;
if (identity != null) {
    target = context.getObjectById(Identity.class, identity);
}

// Work out who should receive the notification.
String recipient = null;
if (deprovisionEmailRecipient != null && deprovisionEmailRecipient.trim().length() > 0) {
    recipient = deprovisionEmailRecipient.trim();
}
if (recipient == null && target != null) {
    Identity mgr = target.getManager();
    if (mgr != null && mgr.getEmail() != null) {
        recipient = mgr.getEmail();
    }
    if (recipient == null && target.getEmail() != null) {
        recipient = target.getEmail();
    }
}
// Final fallback - point this at your IAM / security mailbox.
if (recipient == null || recipient.length() == 0) {
    recipient = "iam-notifications@example.com";
}

EmailTemplate template = context.getObjectByName(EmailTemplate.class, deprovisionEmailTemplate);
if (template == null) {
    log.error("Scheduled Assignment: deprovision email template not found: " + deprovisionEmailTemplate);
} else {
    Map args = new HashMap();
    args.put("identityName", identityName);
    args.put("eventType", eventType);
    args.put("roleName", roleName);
    args.put("applicationName", applicationName);
    args.put("nativeIdentity", nativeIdentity);
    args.put("attributeName", name);
    args.put("attributeValue", value);
    args.put("assigner", assigner);

    EmailOptions options = new EmailOptions(recipient, args);
    context.sendEmailNotification(template, options);
} 
System.out.println("eventType = " + eventType);
System.out.println("roleName = " + roleName);
System.out.println("recipient = " + recipient);
